/* eslint-disable react-hooks/exhaustive-deps */
import React, { useRef, useEffect, useState, memo } from 'react';
import { useGLTF } from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import * as THREE from "three";


// ============================================
// 🎭 LIP SYNC MANAGER
// ============================================
const LipSyncManager = ({ scene, isSpeaking }) => {
  useEffect(() => {
    if (!scene) return;

    const meshes = [];
    scene.traverse((child) => {
      if (child.isMesh && child.morphTargetInfluences) {
        meshes.push(child);
      }
    });

    console.log(`👄 Found ${meshes.length} meshes with morph targets`);

    let lipSyncInterval;
    if (isSpeaking && meshes.length > 0) {
      lipSyncInterval = setInterval(() => {
        meshes.forEach(mesh => {
          if (mesh.morphTargetDictionary && mesh.morphTargetInfluences) {
            const dict = mesh.morphTargetDictionary;
            const lipTargets = Object.keys(dict).filter(key => 
              key.toLowerCase().includes('lip') || 
              key.toLowerCase().includes('mouth') ||
              key.toLowerCase().includes('jaw') ||
              key.toLowerCase().includes('viseme')
            );
            
            if (lipTargets.length > 0) {
              const randomLip = lipTargets[Math.floor(Math.random() * lipTargets.length)];
              const index = dict[randomLip];
              mesh.morphTargetInfluences[index] = Math.random() * 0.6 + 0.3;
            }
          }
        });
      }, 80);
    } else {
      // Reset morph targets when not speaking
      meshes.forEach(mesh => {
        if (mesh.morphTargetInfluences) {
          for (let i = 0; i < mesh.morphTargetInfluences.length; i++) {
            mesh.morphTargetInfluences[i] = 0;
          }
        }
      });
    }

    return () => {
      clearInterval(lipSyncInterval);
      meshes.forEach(mesh => {
        if (mesh.morphTargetInfluences) {
          for (let i = 0; i < mesh.morphTargetInfluences.length; i++) {
            mesh.morphTargetInfluences[i] = 0;
          }
        }
      });
    };
  }, [isSpeaking, scene]);

  return null;
};


// ============================================
// 🎭 FEMALE AVATAR (Priya)
// ============================================
const FemaleAvatar = memo(({ avatarMode, isAISpeaking, onIntroComplete }) => {
  const group = useRef();
  const mixerRef = useRef();
  const actionsRef = useRef({});
  const currentActionRef = useRef(null);
  const talkingIndexRef = useRef(0);
  const idleIndexRef = useRef(0);
  const hasCalledIntroRef = useRef(false);
  const isIdleCycleActiveRef = useRef(true);

  const { scene } = useGLTF("/avatars/priya.glb");
  const walkGltf = useGLTF("/animations/female/F_Walk_002.glb");
  const danceGltf = useGLTF("/animations/female/F_Dances_001.glb");
  const crouchGltf = useGLTF("/animations/female/F_Crouch_Walk_001.glb");
  
  const idleVar1Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_001.glb");
  const idleVar2Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_002.glb");
  const idleVar3Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_003.glb");
  const idleVar4Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_004.glb");
  const idleVar5Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_005.glb");
  const idleVar6Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_006.glb");
  const idleVar7Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_007.glb");
  const idleVar8Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_008.glb");
  const idleVar9Gltf = useGLTF("/animations/female/F_Standing_Idle_Variations_009.glb");
  
  const talk1Gltf = useGLTF("/animations/female/F_Talking_Variations_001.glb");
  const talk2Gltf = useGLTF("/animations/female/F_Talking_Variations_002.glb");
  const talk3Gltf = useGLTF("/animations/female/F_Talking_Variations_003.glb");
  const talk4Gltf = useGLTF("/animations/female/F_Talking_Variations_004.glb");
  const talk5Gltf = useGLTF("/animations/female/F_Talking_Variations_005.glb");
  const talk6Gltf = useGLTF("/animations/female/F_Talking_Variations_006.glb");

  useEffect(() => {
    if (!scene) return;

    console.log("🎬 Setting up Priya");
    mixerRef.current = new THREE.AnimationMixer(scene);

    const animationsData = {
      idleVar1: { clips: idleVar1Gltf.animations, speed: 0.8 },
      idleVar2: { clips: idleVar2Gltf.animations, speed: 0.8 },
      idleVar3: { clips: idleVar3Gltf.animations, speed: 0.8 },
      idleVar4: { clips: idleVar4Gltf.animations, speed: 0.8 },
      idleVar5: { clips: idleVar5Gltf.animations, speed: 0.8 },
      idleVar6: { clips: idleVar6Gltf.animations, speed: 0.8 },
      idleVar7: { clips: idleVar7Gltf.animations, speed: 0.8 },
      idleVar8: { clips: idleVar8Gltf.animations, speed: 0.8 },
      idleVar9: { clips: idleVar9Gltf.animations, speed: 0.8 },
      talk1: { clips: talk1Gltf.animations, speed: 1.0 },
      talk2: { clips: talk2Gltf.animations, speed: 1.0 },
      talk3: { clips: talk3Gltf.animations, speed: 1.0 },
      talk4: { clips: talk4Gltf.animations, speed: 1.0 },
      talk5: { clips: talk5Gltf.animations, speed: 1.0 },
      talk6: { clips: talk6Gltf.animations, speed: 1.0 },
      walk: { clips: walkGltf.animations, speed: 0.9 },
      dance: { clips: danceGltf.animations, speed: 0.9 },
      crouch: { clips: crouchGltf.animations, speed: 0.8 },
    };

    Object.entries(animationsData).forEach(([name, config]) => {
      if (config.clips?.length > 0) {
        const action = mixerRef.current.clipAction(config.clips[0]);
        action.setLoop(THREE.LoopOnce);
        action.clampWhenFinished = true;
        action.timeScale = config.speed;
        actionsRef.current[name] = action;
      }
    });

    if (!hasCalledIntroRef.current) {
      hasCalledIntroRef.current = true;
      setTimeout(() => {
        playIdleCycle();
        if (onIntroComplete) {
          onIntroComplete({
            message: "Hi! I'm Priya, your Biology tutor. I'm so excited to explore the fascinating world of life sciences with you today!",
            companionId: 'priya_biology',
          });
        }
      }, 800);
    }

    return () => mixerRef.current?.stopAllAction();
  }, [scene]);

  const playIdleCycle = () => {
    if (!isIdleCycleActiveRef.current) return;
    
    const idleVariations = ['idleVar1', 'idleVar2', 'idleVar3', 'idleVar4', 'idleVar5', 'idleVar6', 'idleVar7', 'idleVar8', 'idleVar9'];
    const variation = idleVariations[idleIndexRef.current % idleVariations.length];
    
    playAnimation(variation, () => {
      idleIndexRef.current++;
      playIdleCycle();
    });
  };

  const playTalkingCycle = () => {
    if (avatarMode !== "talk") {
      isIdleCycleActiveRef.current = true;
      idleIndexRef.current = 0;
      playIdleCycle();
      return;
    }
    
    const talkingAnimations = ['talk1', 'talk2', 'talk3', 'talk4', 'talk5', 'talk6'];
    const currentTalk = talkingAnimations[talkingIndexRef.current % talkingAnimations.length];
    
    playAnimation(currentTalk, () => {
      talkingIndexRef.current++;
      if (avatarMode === "talk") {
        playTalkingCycle();
      } else {
        isIdleCycleActiveRef.current = true;
        idleIndexRef.current = 0;
        playIdleCycle();
      }
    });
  };

  const playAnimation = (name, onFinish) => {
    const action = actionsRef.current[name];
    if (!action) {
      onFinish?.();
      return;
    }

    if (currentActionRef.current && currentActionRef.current !== action) {
      currentActionRef.current.fadeOut(0.3);
    }

    action.reset().fadeIn(0.3).play();
    currentActionRef.current = action;

    if (onFinish) {
      const handler = (e) => {
        if (e.action === action) {
          mixerRef.current.removeEventListener("finished", handler);
          onFinish();
        }
      };
      mixerRef.current.addEventListener("finished", handler);
    }
  };

  useEffect(() => {
    if (!actionsRef.current.idleVar1) return;

    if (avatarMode === 'walk' || avatarMode === 'dance' || avatarMode === 'crouch' || avatarMode === 'sit') {
      isIdleCycleActiveRef.current = false;
      const animMap = { sit: 'crouch' };
      const animName = animMap[avatarMode] || avatarMode;
      
      if (actionsRef.current[animName]) {
        playAnimation(animName, () => {
          isIdleCycleActiveRef.current = true;
          playIdleCycle();
        });
      }
      return;
    }

    if (avatarMode === "talk") {
      isIdleCycleActiveRef.current = false;
      talkingIndexRef.current = 0;
      playTalkingCycle();
    } else if (avatarMode === "idle") {
      if (!isIdleCycleActiveRef.current) {
        isIdleCycleActiveRef.current = true;
        idleIndexRef.current = 0;
        playIdleCycle();
      }
    }
  }, [avatarMode]);

  useEffect(() => {
    const clock = new THREE.Clock();
    let frameId;
    
    const animate = () => {
      frameId = requestAnimationFrame(animate);
      const delta = clock.getDelta();
      if (delta < 0.1) {
        mixerRef.current?.update(delta);
      }
    };
    
    frameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameId);
  }, []);

  return (
    <group ref={group}>
      <primitive object={scene} scale={1.6} position={[0, -2.2, 0]} />
      <LipSyncManager scene={scene} isSpeaking={isAISpeaking} />
    </group>
  );
});

FemaleAvatar.displayName = 'FemaleAvatar';


// ============================================
// 🎭 MALE AVATAR (Omkar)
// ============================================
const MaleAvatar = memo(({ avatarMode, isAISpeaking, onIntroComplete }) => {
  const group = useRef();
  const mixerRef = useRef();
  const actionsRef = useRef({});
  const currentActionRef = useRef(null);
  const talkingIndexRef = useRef(0);
  const idleIndexRef = useRef(0);
  const hasCalledIntroRef = useRef(false);
  const isIdleCycleActiveRef = useRef(true);

  const { scene } = useGLTF("/avatars/omkar.glb");
  const walkGltf = useGLTF("/animations/male/M_Walk_001.glb");
  const danceGltf = useGLTF("/animations/male/M_Dances_001.glb");
  const jumpGltf = useGLTF("/animations/male/M_Jog_Jump_001.glb");
  const crouchGltf = useGLTF("/animations/male/M_Crouch_Walk_003.glb");

  const idleVar1Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_001.glb");
  const idleVar2Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_002.glb");
  const idleVar3Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_003.glb");
  const idleVar4Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_004.glb");
  const idleVar5Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_005.glb");
  const idleVar6Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_006.glb");
  const idleVar7Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_007.glb");
  const idleVar8Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_008.glb");
  const idleVar9Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_009.glb");
  const idleVar10Gltf = useGLTF("/animations/male/M_Standing_Idle_Variations_010.glb");
  
  const expr1Gltf = useGLTF("/animations/male/M_Standing_Expressions_001.glb");
  const expr2Gltf = useGLTF("/animations/male/M_Standing_Expressions_002.glb");
  const expr4Gltf = useGLTF("/animations/male/M_Standing_Expressions_004.glb");
  const expr5Gltf = useGLTF("/animations/male/M_Standing_Expressions_005.glb");
  
  const talk1Gltf = useGLTF("/animations/male/M_Talking_Variations_001.glb");
  const talk2Gltf = useGLTF("/animations/male/M_Talking_Variations_002.glb");
  const talk3Gltf = useGLTF("/animations/male/M_Talking_Variations_003.glb");
  const talk4Gltf = useGLTF("/animations/male/M_Talking_Variations_004.glb");
  const talk5Gltf = useGLTF("/animations/male/M_Talking_Variations_005.glb");
  const talk6Gltf = useGLTF("/animations/male/M_Talking_Variations_006.glb");
  const talk7Gltf = useGLTF("/animations/male/M_Talking_Variations_007.glb");
  const talk8Gltf = useGLTF("/animations/male/M_Talking_Variations_008.glb");
  const talk9Gltf = useGLTF("/animations/male/M_Talking_Variations_009.glb");
  const talk10Gltf = useGLTF("/animations/male/M_Talking_Variations_010.glb");

  useEffect(() => {
    if (!scene) return;

    console.log("🎬 Setting up Omkar");
    mixerRef.current = new THREE.AnimationMixer(scene);

    const animationsData = {
      idleVar1: { clips: idleVar1Gltf.animations, speed: 0.8 },
      idleVar2: { clips: idleVar2Gltf.animations, speed: 0.8 },
      idleVar3: { clips: idleVar3Gltf.animations, speed: 0.8 },
      idleVar4: { clips: idleVar4Gltf.animations, speed: 0.8 },
      idleVar5: { clips: idleVar5Gltf.animations, speed: 0.8 },
      idleVar6: { clips: idleVar6Gltf.animations, speed: 0.8 },
      idleVar7: { clips: idleVar7Gltf.animations, speed: 0.8 },
      idleVar8: { clips: idleVar8Gltf.animations, speed: 0.8 },
      idleVar9: { clips: idleVar9Gltf.animations, speed: 0.8 },
      idleVar10: { clips: idleVar10Gltf.animations, speed: 0.8 },
      expr1: { clips: expr1Gltf.animations, speed: 0.8 },
      expr2: { clips: expr2Gltf.animations, speed: 0.8 },
      expr4: { clips: expr4Gltf.animations, speed: 0.8 },
      expr5: { clips: expr5Gltf.animations, speed: 0.8 },
      talk1: { clips: talk1Gltf.animations, speed: 1.0 },
      talk2: { clips: talk2Gltf.animations, speed: 1.0 },
      talk3: { clips: talk3Gltf.animations, speed: 1.0 },
      talk4: { clips: talk4Gltf.animations, speed: 1.0 },
      talk5: { clips: talk5Gltf.animations, speed: 1.0 },
      talk6: { clips: talk6Gltf.animations, speed: 1.0 },
      talk7: { clips: talk7Gltf.animations, speed: 1.0 },
      talk8: { clips: talk8Gltf.animations, speed: 1.0 },
      talk9: { clips: talk9Gltf.animations, speed: 1.0 },
      talk10: { clips: talk10Gltf.animations, speed: 1.0 },
      walk: { clips: walkGltf.animations, speed: 0.9 },
      dance: { clips: danceGltf.animations, speed: 0.9 },
      crouch: { clips: crouchGltf.animations, speed: 0.8 },
      jump: { clips: jumpGltf.animations, speed: 0.9 },
    };

    Object.entries(animationsData).forEach(([name, config]) => {
      if (config.clips?.length > 0) {
        const action = mixerRef.current.clipAction(config.clips[0]);
        action.setLoop(THREE.LoopOnce);
        action.clampWhenFinished = true;
        action.timeScale = config.speed;
        actionsRef.current[name] = action;
      }
    });

    if (!hasCalledIntroRef.current) {
      hasCalledIntroRef.current = true;
      setTimeout(() => {
        playIdleCycle();
        if (onIntroComplete) {
          onIntroComplete({
            message: "Hey there! I'm Omkar, your AI tutor. I'm excited to explore artificial intelligence and machine learning concepts with you today!",
            companionId: 'omkar_ai',
          });
        }
      }, 800);
    }

    return () => mixerRef.current?.stopAllAction();
  }, [scene]);

  const playIdleCycle = () => {
    if (!isIdleCycleActiveRef.current) return;
    
    const idleVariations = ['idleVar1', 'idleVar2', 'idleVar3', 'idleVar4', 'idleVar5', 'idleVar6', 'idleVar7', 'idleVar8', 'idleVar9', 'idleVar10'];
    const expressions = ['expr1', 'expr2', 'expr4', 'expr5'];
    
    const variation = idleVariations[idleIndexRef.current % idleVariations.length];
    
    playAnimation(variation, () => {
      idleIndexRef.current++;
      
      if (idleIndexRef.current % 4 === 0) {
        const expr = expressions[Math.floor(Math.random() * expressions.length)];
        playAnimation(expr, () => playIdleCycle());
      } else {
        playIdleCycle();
      }
    });
  };

  const playTalkingCycle = () => {
    if (avatarMode !== "talk") {
      isIdleCycleActiveRef.current = true;
      idleIndexRef.current = 0;
      playIdleCycle();
      return;
    }
    
    const talkingAnimations = ['talk1', 'talk2', 'talk3', 'talk4', 'talk5', 'talk6', 'talk7', 'talk8', 'talk9', 'talk10'];
    const currentTalk = talkingAnimations[talkingIndexRef.current % talkingAnimations.length];
    
    playAnimation(currentTalk, () => {
      talkingIndexRef.current++;
      if (avatarMode === "talk") {
        playTalkingCycle();
      } else {
        isIdleCycleActiveRef.current = true;
        idleIndexRef.current = 0;
        playIdleCycle();
      }
    });
  };

  const playAnimation = (name, onFinish) => {
    const action = actionsRef.current[name];
    if (!action) {
      onFinish?.();
      return;
    }

    if (currentActionRef.current && currentActionRef.current !== action) {
      currentActionRef.current.fadeOut(0.3);
    }

    action.reset().fadeIn(0.3).play();
    currentActionRef.current = action;

    if (onFinish) {
      const handler = (e) => {
        if (e.action === action) {
          mixerRef.current.removeEventListener("finished", handler);
          onFinish();
        }
      };
      mixerRef.current.addEventListener("finished", handler);
    }
  };

  useEffect(() => {
    if (!actionsRef.current.idleVar1) return;

    if (avatarMode === 'walk' || avatarMode === 'dance' || avatarMode === 'jump' || avatarMode === 'crouch' || avatarMode === 'sit' || avatarMode === 'wave') {
      isIdleCycleActiveRef.current = false;
      const animMap = { sit: 'crouch', wave: 'expr1' };
      const animName = animMap[avatarMode] || avatarMode;
      
      if (actionsRef.current[animName]) {
        playAnimation(animName, () => {
          isIdleCycleActiveRef.current = true;
          playIdleCycle();
        });
      }
      return;
    }

    if (avatarMode === "talk") {
      isIdleCycleActiveRef.current = false;
      talkingIndexRef.current = 0;
      playTalkingCycle();
    } else if (avatarMode === "idle") {
      if (!isIdleCycleActiveRef.current) {
        isIdleCycleActiveRef.current = true;
        idleIndexRef.current = 0;
        playIdleCycle();
      }
    }
  }, [avatarMode]);

  useEffect(() => {
    const clock = new THREE.Clock();
    let frameId;
    
    const animate = () => {
      frameId = requestAnimationFrame(animate);
      const delta = clock.getDelta();
      if (delta < 0.1) {
        mixerRef.current?.update(delta);
      }
    };
    
    frameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameId);
  }, []);

  return (
    <group ref={group}>
      <primitive object={scene} scale={1.6} position={[0, -2.2, 0]} />
      <LipSyncManager scene={scene} isSpeaking={isAISpeaking} />
    </group>
  );
});

MaleAvatar.displayName = 'MaleAvatar';


